() => {
  const nav = document.querySelector('main nav') || document.querySelector('nav');
  const out = { navText: nav ? nav.innerText : null };
  // collect group labels and buttons in the system management nav
  if (nav) {
    out.children = Array.from(nav.children).map(c => ({tag: c.tagName, text: c.innerText.slice(0,40), cls: c.className.slice(0,80)}));
  }
  // find the selected button styling
  if (nav) {
    out.buttons = Array.from(nav.querySelectorAll('button')).map(b => ({
      text: b.innerText.trim(),
      class: b.className,
      ariaSelected: b.getAttribute('aria-selected'),
      style: b.getAttribute('style')
    }));
  }
  return out;
}

