() => {
  const el = Array.from(document.querySelectorAll('main *')).find(e => e.className && typeof e.className === 'string' && e.className.includes('overflow-y-auto p-6 space-y-6'));
  if (!el) return 'not found';
  el.scrollTop = 0;
  el.scrollTop = el.scrollHeight - el.clientHeight;
  return {scrollTop: el.scrollTop, scrollHeight: el.scrollHeight, clientHeight: el.clientHeight};
}

