() => {
  const html = document.documentElement;
  const body = document.body;
  const out = {
    htmlClass: html.className,
    bodyClass: body.className,
    dataTheme: html.getAttribute('data-theme') || body.getAttribute('data-theme'),
    bodyBg: getComputedStyle(body).backgroundColor,
    storedTheme: localStorage.getItem('theme') || localStorage.getItem('app-theme') || null
  };
  // system management nav buttons
  const nav = document.querySelector('main nav');
  if (nav) {
    out.navButtons = Array.from(nav.querySelectorAll('button')).map(b => {
      const cs = getComputedStyle(b);
      return {text: b.textContent.trim(), color: cs.color, bg: cs.backgroundColor, borderLeft: cs.borderLeft};
    });
  }
  return out;
}

() => {
  const nav = document.querySelector('main nav');
  const navCS = getComputedStyle(nav);
  const out = {
    navBg: navCS.backgroundColor,
    navParentBg: nav.parentElement ? getComputedStyle(nav.parentElement).backgroundColor : null,
    buttons: []
  };
  Array.from(nav.querySelectorAll('button')).forEach(b => {
    const svg = b.querySelector('svg');
    const svgCS = svg ? getComputedStyle(svg) : null;
    // find absolute positioned bar
    const bar = b.querySelector('span.absolute, .absolute');
    const barCS = bar ? getComputedStyle(bar) : null;
    out.buttons.push({
      text: b.textContent.trim(),
      cls: b.className,
      iconColor: svgCS ? (svgCS.color + ' / stroke=' + svgCS.stroke) : null,
      barBg: barCS ? barCS.backgroundColor : null,
      barCls: bar ? bar.className : null,
      textColor: getComputedStyle(b).color
    });
  });
  return out;
}

() => {
  const nav = document.querySelector('main nav');
  const chain = [];
  let el = nav;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    chain.push({tag: el.tagName, cls: (el.className||'').toString().slice(0,80), bg: cs.backgroundColor, color: cs.color});
    el = el.parentElement;
  }
  // also check the main element bg
  const main = document.querySelector('main');
  return {chain, mainBg: getComputedStyle(main).backgroundColor, htmlBg: getComputedStyle(document.documentElement).backgroundColor};
}

