() => {
  const out = { lightRules: [], slateRules: [] };
  try {
    for (const sheet of Array.from(document.styleSheets)) {
      let rules;
      try { rules = sheet.cssRules; } catch(e){ continue; }
      if (!rules) continue;
      for (const r of Array.from(rules)) {
        const t = r.cssText || '';
        if (t.includes('.light') && (t.includes('slate-400') || t.includes('slate-100') || t.includes('slate-800') || t.includes('color'))) {
          if (out.lightRules.length < 25) out.lightRules.push(t.slice(0,200));
        }
      }
    }
  } catch(e) { out.err = String(e); }
  return out;
}
